            Question("لو هتسأل آخر سؤال جنسي صريح، تختار إيه؟", listOf("إيه اللي نفسك تجربه بس متردد؟", "إيه اللي خلاك تحس بقربنا أكتر؟", "إيه اللي نحتاج نغيره عشان نرتاح؟")),
        )),
    )
}
